// point-in-polygon (ray casting); координати [lng, lat]; кільця-дірки віднімаються
function ring(r, x, y) {
  let inside = false;
  for (let i = 0, j = r.length - 1; i < r.length; j = i++) {
    const xi = r[i][0], yi = r[i][1], xj = r[j][0], yj = r[j][1];
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}
function poly(p, x, y) {
  if (!ring(p[0], x, y)) return false;
  for (let i = 1; i < p.length; i++) if (ring(p[i], x, y)) return false;
  return true;
}
export function inGeometry(g, lat, lng) {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return false;
  if (g.type === "Polygon") return poly(g.coordinates, lng, lat);
  if (g.type === "MultiPolygon") return g.coordinates.some((p) => poly(p, lng, lat));
  return false;
}
export function inZone(lat, lng) {
  return ZONE.some((g) => inGeometry(g, lat, lng));
}
